using ForensicEdu.Mobile.Controls;
using ForensicEdu.Mobile.Core.Models;
namespace ForensicEdu.Mobile.Pages;
public sealed class PaymentsPage:AcademyPage
{
 private List<Payment> payments=[];private readonly VerticalStackLayout results=new(){Spacing=12};private readonly SearchBar search=new(){Placeholder="Curso, orden, banco u operación"};private readonly Picker status=new(){Title="Estado del pago"};
 public PaymentsPage(IServiceProvider s):base(s,"Mis pagos"){foreach(var label in new[]{"Todos","Pendiente","En revisión","Aprobado","Observado","Rechazado","Duplicado"})status.Items.Add(label);status.SelectedIndex=0;search.TextChanged+=(_,_)=>Draw();status.SelectedIndexChanged+=(_,_)=>Draw();}
 protected override async void OnAppearing(){base.OnAppearing();if(!RequireAccount())return;Body.Clear();Header("MI EXPEDIENTE","Mis pagos","Consulta los pagos de tus cursos, eventos y asesorías.");Body.Add(Ui.Action("Actualizar pagos",Reload,true));Body.Add(search);Body.Add(status);if(results.Parent is Layout previous)previous.Remove(results);Body.Add(results);await Reload();}
 private Task Reload()=>Run(async()=>{payments=await Api.AllAsync<Payment>("student/payments");Draw();});
 private void Draw(){results.Clear();var query=(search.Text??"").Trim();var visible=payments.Where(p=>(status.SelectedIndex<=0||p.StatusLabel==status.SelectedItem?.ToString())&&$"{p.ProductTitle} {p.OrderCode} {p.BankName} {p.OperationNumber}".Contains(query,StringComparison.OrdinalIgnoreCase)).OrderByDescending(p=>p.RegisteredAt).ToList();results.Add(Ui.Text($"{visible.Count} de {payments.Count} pagos",12,false,"Muted"));foreach(var p in visible){var stack=Ui.Stack(Ui.Eyebrow(p.StatusLabel),Ui.Text(p.ProductTitle,20,true),Ui.Text($"S/ {p.Amount:0.00}",23,true),Ui.Text($"Orden: {p.OrderCode}\nBanco: {p.BankName}\nOperación: {p.OperationNumber}\nTitular: {p.AccountHolderName}\nFecha de pago: {p.OperationDate:dd/MM/yyyy}\nRegistrado: {p.RegisteredAt.ToLocalTime():dd/MM/yyyy HH:mm}",12,false,"Muted"),Ui.Text(p.HasVoucher?"Comprobante recibido":"Comprobante pendiente de adjuntar",12));if(p.ReviewedAt is {} reviewed)stack.Add(Ui.Text($"Revisado: {reviewed.ToLocalTime():dd/MM/yyyy HH:mm}",12,false,"Muted"));results.Add(Ui.Card(stack));}if(visible.Count==0)results.Add(Ui.Text(payments.Count==0?"Aún no tienes pagos registrados.":"No hay pagos que coincidan con los filtros.",14,false,"Muted"));}
}
